        uniffiFree: { (uniffiHandle: UInt64) -> () in
            do {
                try FfiConverterTypeAuthTokenProvider.handleMap.remove(handle: uniffiHandle)
            } catch {
                print("Uniffi callback interface AuthTokenProvider: handle missing in uniffiFree")
            }
