/**
 * A failure reported across the native boundary.
 */
public 
enum RuntimeError: Swift.Error, Equatable, Hashable, Foundation.LocalizedError {

    
    
    /**
     * The runtime, transport, or Convex client failed locally.
     */
    case Internal(message: String
    )
    /**
     * The deployment reported an unexpected function failure.
     */
    case Server(message: String
    )
    /**
     * A Convex function threw a `ConvexError`; `data` is its Convex-encoded JSON payload.
     */
    case Application(data: String
    )
    /**
     * The function path or an argument was not valid Convex input. Nothing was sent.
     */
    case InvalidRequest(message: String
    )
    /**
     * The caller's cancellation signal fired before the operation completed.
     */
    case Cancelled

    

    

    
    public var errorDescription: String? {
        String(reflecting: self)
    }
    
}

#if compiler(>=6)
extension RuntimeError: Sendable {}
#endif

#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public struct FfiConverterTypeRuntimeError: FfiConverterRustBuffer {
    typealias SwiftType = RuntimeError

    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> RuntimeError {
        let variant: Int32 = try readInt(&buf)
        switch variant {

        

        
        case 1: return .Internal(
            message: try FfiConverterString.read(from: &buf)
            )
        case 2: return .Server(
            message: try FfiConverterString.read(from: &buf)
            )
        case 3: return .Application(
            data: try FfiConverterString.read(from: &buf)
            )
        case 4: return .InvalidRequest(
            message: try FfiConverterString.read(from: &buf)
            )
        case 5: return .Cancelled

         default: throw UniffiInternalError.unexpectedEnumCase
        }
    }

    public static func write(_ value: RuntimeError, into buf: inout [UInt8]) {
        switch value {

        

        
        
        case let .Internal(message):
            writeInt(&buf, Int32(1))
            FfiConverterString.write(message, into: &buf)
            
        
        case let .Server(message):
            writeInt(&buf, Int32(2))
            FfiConverterString.write(message, into: &buf)
            
        
        case let .Application(data):
            writeInt(&buf, Int32(3))
            FfiConverterString.write(data, into: &buf)
            
        
        case let .InvalidRequest(message):
            writeInt(&buf, Int32(4))
            FfiConverterString.write(message, into: &buf)
            
        
        case .Cancelled:
            writeInt(&buf, Int32(5))
        
        }
    }
}


